use std::collections::HashSet;

fn remove_elements(a: &[i32], b: &[i32]) -> Vec<i32> {
    // Create a HashSet from the second slice for O(1) lookups
    let b_set: HashSet<i32> = b.iter().cloned().collect();
    
    // Create a HashSet to track unique elements in the result
    let mut result_set: HashSet<i32> = HashSet::new();
    
    // Iterate over the first slice and add elements to the result if they are not in b_set
    for &value in a {
        if !b_set.contains(&value) {
            result_set.insert(value);
        }
    }
    
    // Convert the HashSet back to a Vec and return it
    result_set.into_iter().collect()
}

// Example usage
fn main() {
    let a = vec![1, 2, 3, 4, 5, 2];
    let b = vec![2, 4];
    let result = remove_elements(&a, &b);
    println!("{:?}", result); // Output could be [1, 3, 5] (order may vary)
}